exports.id=712,exports.ids=[712],exports.modules={9107:()=>{},122:(e,a,t)=>{Promise.resolve().then(t.t.bind(t,3642,23)),Promise.resolve().then(t.t.bind(t,7586,23)),Promise.resolve().then(t.t.bind(t,7838,23)),Promise.resolve().then(t.t.bind(t,8057,23)),Promise.resolve().then(t.t.bind(t,7741,23)),Promise.resolve().then(t.t.bind(t,3118,23))},1047:(e,a,t)=>{"use strict";t.d(a,{ZW:()=>r,nO:()=>s,PR:()=>n,sY:()=>o});let o={zh:{meta:{title:"PawMatch 趣味测试",description:"10问轻松测出你是哪种犬种人格。"},language:{label:"语言",zh:"中文",ja:"日本語",en:"English"},home:{eyebrow:"PawMatch 趣味测试",title:"如果你是狗狗，你会是哪种犬种？",description:"\uD83D\uDC3E 测测你的内在“狗格”\uD83D\uDC3E",start:"开始测试",meta:"共 10 题 \xb7 约 1 分钟 \xb7 纯属娱乐"},quiz:{previous:"上一题",next:"下一题",reveal:"查看我的犬种",progress:"{current} / {total}",home:"返回首页"},result:{revealTitle:"你的狗格是——",secondaryPrefix:"你也有一点像 {breed}",cuteFlawLabel:"可爱的小缺点",saveImage:"保存 PNG",share:"系统分享",email:"邮件分享",copy:"复制文案",copied:"已复制",retry:"重新测试",loading:"加载中...",privacy:"PawMatch 趣味测试的答案和计算均在你的浏览器中完成。当前版本不要求登录，不收集姓名、邮箱或完整答题记录。",entertainment:"本测试为娱乐内容，犬种结果是人格化创作，不代表对真实犬种、犬只个体或用户心理特征的专业判断。"},notices:{entertainment:"本测试为娱乐内容，犬种结果是人格化创作，不代表对真实犬种、犬只个体或用户心理特征的专业判断。",privacy:"PawMatch 趣味测试的答案和计算均在你的浏览器中完成。当前版本不要求登录，不收集姓名、邮箱或完整答题记录。",imageFallback:"生成图片失败，请使用浏览器截图，或复制结果文字。",attachmentHint:"图片已保存，请在邮件中手动添加附件。"},questions:{q1:{text:"终于到周末，你最想怎么过？",options:{A:"窝在沙发看电影，谁也别叫我",B:"和熟悉的朋友吃饭聊天",C:"去公园散步、运动或爬山",D:"临时出发去陌生地方探险"}},q2:{text:"进入一个全是陌生人的聚会，你通常会？",options:{A:"十分钟后已经和大家聊熟",B:"先找一个看起来友善的人说话",C:"安静观察，熟了才打开",D:"站在朋友旁边，顺便默默判断所有人"}},q3:{text:"面对一个新任务，你的第一反应是？",options:{A:"直接上手，边做边学",B:"先研究清楚，再制定计划",C:"拉上别人一起做更有动力",D:"先看我有没有兴趣，没有就放着"}},q4:{text:"朋友临时取消约定，你会？",options:{A:"马上找下一场活动",B:"有点失落，但很快安排自己的事",C:"表面没事，心里会默默记住",D:"太好了，我正想独处"}},q5:{text:"朋友最常用哪个词形容你？",options:{A:"热情开心果",B:"靠谱又温柔",C:"聪明又较真",D:"独立有个性"}},q6:{text:"你迷路时通常怎么处理？",options:{A:"自信地继续走，剧情更精彩",B:"打开地图，快速修正路线",C:"找人问路，顺便认识新朋友",D:"我没迷路，只是选择了另一条路线"}},q7:{text:"团队突然陷入混乱时，你更像？",options:{A:"活跃气氛，让大家先别慌",B:"整理任务，把事情一步步推进",C:"先看看谁状态不好，并照顾他",D:"指出真正的问题，即使别人不爱听"}},q8:{text:"如果能选一种超能力，你想要？",options:{A:"读心术：马上知道大家在想什么",B:"分身术：同时完成所有事情",C:"瞬间移动：随时去任何地方",D:"超级感官：发现别人忽略的细节"}},q9:{text:"面对规则，你更接近？",options:{A:"合理就遵守，不合理就讨论",B:"规则让我安心，我会认真执行",C:"先试试能不能偷偷绕过去",D:"我有自己的规则，谢谢"}},q10:{text:"你通常怎样表达喜欢？",options:{A:"热情说出来，并主动靠近",B:"默默记住并照顾对方的需要",C:"一起做有趣的事，制造回忆",D:"不总说出口，但会一直留在身边"}}},breeds:{"golden-retriever":{name:"金毛寻回犬",tags:["温暖","友善","安心感"],summary:"你很容易让人放下戒心。你愿意听朋友说话，也会自然地把落单的人拉进圈子。你不是没有情绪，只是常常先照顾气氛和别人的感受。",flaw:"有时太想让所有人开心，忘了自己也可以先休息。",share:"我是金毛型人格：朋友群里的安心充电站。"},labrador:{name:"拉布拉多",tags:["乐观","行动派","团队感"],summary:"你倾向先行动，再边走边修正。遇到新任务时，你的能量往往会感染身边的人。你重视合作，也不介意在关键时刻多做一点。",flaw:"兴奋起来容易答应太多事，之后才发现自己的行程已经塞满。",share:"我是拉布拉多型人格：乐观的行动派。"},poodle:{name:"贵宾犬",tags:["聪明","敏锐","有品位"],summary:"你观察得快，学得也快，常能注意到别人忽略的小细节。你对环境、表达和做事方式都有自己的标准，不喜欢粗糙地应付。",flaw:"标准一高，就可能在一个小细节上纠结得比所有人都久。",share:"我是贵宾型人格：聪明、敏锐，还有一点讲究。"},"border-collie":{name:"边境牧羊犬",tags:["高效","专注","战略家"],summary:"当别人还在讨论从哪里开始，你已经悄悄整理好了步骤。你喜欢理解系统、发现规律，并把混乱变成可执行的计划。",flaw:"看到低效率时，很难忍住不在脑中替所有人重新排流程。",share:"我是边牧型人格：会把混乱自动整理成清单。"},"shiba-inu":{name:"柴犬",tags:["独立","克制","有原则"],summary:"你有自己的节奏和边界，不会为了融入而随便改变立场。面对陌生人时你可能慢热，但认定一个人后，忠诚会体现在长期而稳定的行动里。",flaw:"嘴上说“都可以”，心里其实早已有一个唯一正确答案。",share:"我是柴犬型人格：不讨好，但认定了就很长情。"},husky:{name:"哈士奇",tags:["自由","冒险","剧情体质"],summary:"你的世界很难无聊，因为一个普通计划也可能被你走成全新支线。你好奇、敢试、讨厌被过多规则限制。别人可能猜不到你下一步要做什么。",flaw:"行动速度偶尔超过了计划速度，回头才发现路线好像不太对。",share:"我是哈士奇型人格：自由灵魂，自带剧情。"},samoyed:{name:"萨摩耶",tags:["明亮","热情","聚会磁场"],summary:"你很会把轻松和快乐带进一个空间，也愿意主动靠近别人。你的外表可能让人觉得温和好说话，但其实你有明确的偏好，也很希望自己的情绪和用心得到回应。",flaw:"看起来一直在微笑，心里却可能正在认真等待一句“你今天也很棒”。",share:"我是萨摩耶型人格：负责让大家重新笑起来。"},"german-shepherd":{name:"德国牧羊犬",tags:["可靠","守护","执行力"],summary:"你对承诺很认真，遇到问题时会本能地站出来处理。你不一定是人群中最热闹的那个，却经常是最让人放心的那个。",flaw:"责任心一上线，就容易把本来不属于自己的任务也一起扛走。",share:"我是德牧型人格：不多说，但会把事情接住。"},greyhound:{name:"灵缇",tags:["安静","敏感","松弛感"],summary:"你并不缺乏行动力，只是不愿把能量浪费在无意义的喧闹上。你享受舒服、熟悉、有安全感的空间，也能捕捉到细微的气氛变化。",flaw:"如果沙发足够舒服，再好的计划也可能被推迟五分钟——然后再五分钟。",share:"我是灵缇型人格：该冲刺时冲刺，该躺时绝不勉强。"},corgi:{name:"柯基",tags:["热闹","主见","小队长"],summary:"你很有存在感，能迅速参与话题，也常常自然地开始组织局面。你喜欢和人在一起，但并不代表你没有自己的意见。",flaw:"本来只想提一个建议，最后不知不觉成了整个活动的总导演。",share:"我是柯基型人格：个子可以小，主场必须由我主持。"},beagle:{name:"比格犬",tags:["好奇","探索","兴趣导航"],summary:"你对新鲜线索几乎没有抵抗力。一个有趣的问题、一家没去过的小店，甚至路边突然出现的声音，都可能把你带进新的方向。",flaw:"原本只是查一个问题，回过神时已经打开了十八个标签页。",share:"我是比格型人格：人生靠好奇心导航。"},"french-bulldog":{name:"法国斗牛犬",tags:["松弛","幽默","陪伴感"],summary:"你不迷恋忙碌，也不需要靠宏大计划证明自己。舒服、真诚、有趣的人和事才值得投入。你很会用轻松的方式化解尴尬。",flaw:"对麻烦的预警系统过于灵敏，一察觉复杂就想先坐下来再说。",share:"我是法斗型人格：松弛不是懒，是生活智慧。"}}},ja:{meta:{title:"PawMatch｜もしあなたが犬だったら、何犬？",description:"10問であなたの犬タイプが分かる、気軽なお遊び診断。"},language:{label:"言語を選択",zh:"中文",ja:"日本語",en:"English"},home:{eyebrow:"PawMatch｜もしあなたが犬だったら、何犬？",title:"もしあなたが犬だったら、何犬？",description:"\uD83D\uDC3E まずは内側の「犬グリ」をチェック\uD83D\uDC3E",start:"診断を始める",meta:"全10問・約1分・お遊び診断"},quiz:{previous:"前の質問",next:"次の質問",reveal:"結果を見る",progress:"{current} / {total}",home:"ホームへ戻る"},result:{revealTitle:"あなたの犬タイプは——",secondaryPrefix:"実はちょっとだけ {breed} タイプでもある",cuteFlawLabel:"ちょっと可愛い弱点",saveImage:"画像を保存",share:"結果をシェア",email:"メールで送る",copy:"テキストをコピー",copied:"コピーしました",retry:"もう一度診断",loading:"読み込み中...",privacy:"PawMatchの回答と結果計算は、すべてお使いのブラウザ内で行われます。現在のバージョンではログインは不要で、氏名、メールアドレス、回答内容一式を収集しません。",entertainment:"この診断はエンターテインメント目的です。犬種タイプは人格をイメージした創作であり、実際の犬種や個体、利用者の心理特性に関する専門的な判断ではありません。"},notices:{entertainment:"この診断はエンターテインメント目的です。犬種タイプは人格をイメージした創作であり、実際の犬種や個体、利用者の心理特性に関する専門的な判断ではありません。",privacy:"PawMatchの回答と結果計算は、すべてお使いのブラウザ内で行われます。現在のバージョンではログインは不要で、氏名、メールアドレス、回答内容一式を収集しません。",imageFallback:"画像を作成できませんでした。スクリーンショットを撮るか、結果テキストをコピーしてください。",attachmentHint:"画像を保存しました。メールに手動で添付してください。"},questions:{q1:{text:"やっと週末。いちばんしたいことは？",options:{A:"ソファで映画。今日は誰にも外へ連れ出されたくない",B:"仲のいい友達とごはんを食べながらおしゃべり",C:"公園を散歩したり、運動したり、山に登ったりする",D:"行ったことのない場所へノープランで冒険に出る"}},q2:{text:"知らない人ばかりの集まりでは？",options:{A:"10分もすればみんなと仲良く話せる",B:"まずは親しそうな人を見つけて話しかける",C:"静かに見て、打ち解けてから話す",D:"友達のそばに立って、黙ってみんなを観察する"}},q3:{text:"新しい仕事に向き合うとき、最初の反応は？",options:{A:"とりあえず始めて、やりながら学ぶ",B:"まずちゃんと調べて、計画を立てる",C:"みんなと一緒にやる方がやる気が出る",D:"興味がなければ先に置いておく"}},q4:{text:"友達が急に約束をキャンセルしたら？",options:{A:"すぐ次の予定を探す",B:"ちょっと残念だけど、すぐ自分のことを計画する",C:"表面では大丈夫でも、心の中ではちゃんと覚えておく",D:"ありがたい、ひとりになれる時間だ"}},q5:{text:"友達はあなたをどんな言葉で表す？",options:{A:"熱いハッピーオーラ",B:"頼れるけど優しい",C:"頭がいい、ちょっと厳しい",D:"自立していて個性的"}},q6:{text:"迷子になったら、どうする？",options:{A:"自信満々に進んで、話の展開を盛り上げる",B:"地図を開いて、すぐに修正する",C:"人に聞いて、ついでに新しい友達を作る",D:"迷っていない、ただ別ルートを選んだだけ"}},q7:{text:"チームが突然混乱したとき、あなたは？",options:{A:"空気を盛り上げて、みんなを落ち着かせる",B:"作業を整理して、ひとつずつ進める",C:"まず誰が辛くないか見て、ケアする",D:"本当の問題を指摘する。嫌われてもいい"}},q8:{text:"超能力が一つだけ選べるなら？",options:{A:"心を読む：みんなが何考えてるかすぐわかる",B:"分身：同時にいろんなことを進める",C:"瞬間移動：どこへでもすぐ行ける",D:"超感覚：誰も気づかないポイントを見つける"}},q9:{text:"ルールを前にしたら、あなたは？",options:{A:"理にかなっていれば守る、無理なら議論する",B:"ルールがあると安心。ちゃんと守る",C:"まずはこっそり回避できないか試す",D:"自分のルールがある、ありがとう"}},q10:{text:"好きな気持ちをどう表す？",options:{A:"熱烈に言葉で伝えて、近づく",B:"黙って相手の役に立つことを覚えておく",C:"一緒に楽しいことをして思い出を作る",D:"言葉で言わなくても、ずっとそばにいる"}}},breeds:{"golden-retriever":{name:"ゴールデンレトリーバー",tags:["温かい","親切","安心感"],summary:"あなたは周りの人が緊張しないように自然に導けるタイプです。人の話をよく聞き、落ち込んでいる人を無理なく受け入れます。感情はあるけれど、まず周りの場を整えることが多いです。",flaw:"みんなを笑顔にしたくて、自分の休みまで犠牲にしがち。",share:"私はゴールデン型：みんなを安心させる居場所。"},labrador:{name:"ラブラドール",tags:["楽観的","行動派","チーム感"],summary:"あなたはまず行動し、それから状況に合わせて修正するタイプです。新しいことが起きても、エネルギーで周囲を巻き込みます。協力を大切にし、必要なときは少し多めに手を貸す人です。",flaw:"盛り上がりすぎて、予定を詰め込みすぎることがある。",share:"私はラブラドール型：楽観で動ける人。"},poodle:{name:"プードル",tags:["賢い","鋭い","センスあり"],summary:"あなたは観察が速く、学習も速いです。周りが見逃している細部に気づき、したいことややり方にもこだわります。社交もできるけど、ただの賑やかさではなく、楽しい・きれい・研究したいものに惹かれます。",flaw:"基準が高いだけに、些細なことでも長く悩んでしまう。",share:"私はプードル型：賢くて、ちょっとこだわりがある。"},"border-collie":{name:"ボーダーコリー",tags:["効率的","集中","戦略家"],summary:"みんなが「どこから始めるか」で迷っているとき、あなたはすでに手順を整理していることが多いです。仕組みや法則を見つけ、混乱を実行可能な計画に変えます。",flaw:"非効率さを見ると、頭の中で勝手に作業フローを作ってしまう。",share:"私はボーダーコリー型：混乱を自動で整理するタイプ。"},"shiba-inu":{name:"柴犬",tags:["自立","克制","原則派"],summary:"あなたは自分のペースと境界線を持ち、なかば馴染むために立場を変えません。知らない人に対しては少し時間がかかるものの、信頼した相手に対しては長く安定した思いやりを見せます。",flaw:"「なんでもいい」と言っていても、実は最終的に正解は決まっている。",share:"私は柴犬型：嫌味じゃなくて、認めたら長い付き合い。"},husky:{name:"ハスキー",tags:["自由","冒険","イベント体質"],summary:"あなたの世界は退屈になりにくいです。普通の計画でも、思いがけない支線に変わってしまうことが多いです。好奇心が強く、新しいことを試すのが好き。ルールに縛られるのは苦手です。",flaw:"行動が計画より先に出ることがあり、後から「ちょっと違ったかも」と気づく。",share:"私はハスキー型：自由な魂で、ストーリーが自分で生まれる。"},samoyed:{name:"サモエド",tags:["明るい","情熱的","会場の中心"],summary:"あなたは場を楽しくする力があり、相手に自然に近づけます。見た目は柔らかくても、好みにはちゃんと自分の軸があります。喜びや気持ちをちゃんと返してほしいタイプです。",flaw:"いつも笑って見えるのに、実は「今日も褒めてほしい」と思っていることがある。",share:"私はサモエド型：みんなをまた笑顔にする人。"},"german-shepherd":{name:"ジャーマンシェパード",tags:["頼れる","守る","実行力"],summary:"あなたは約束をちゃんと守り、問題に出会うと本能的に手を差し伸べます。大勢の中で最も熱心ではないかもしれないけど、みんなに安心感を与える人です。",flaw:"責任感が強すぎて、自分のものじゃない仕事まで引き受ける。",share:"私はジャーマン型：口数は少なくても、困ったらちゃんと受け止める。"},greyhound:{name:"グレイハウンド",tags:["静か","敏感","リラックス感"],summary:"あなたは行動力がないわけではありません。ただ、意味のない騒ぎにエネルギーを使うのはあまり好きではありません。快適で安心できる空間を大切にし、細かな空気の変化にも敏感です。",flaw:"ソファが最高なら、最高の計画も5分遅れで始まる。",share:"私はグレイハウンド型：走る時は走る、休む時はちゃんと休む。"},corgi:{name:"コーギー",tags:["賑やか","主見","小隊長"],summary:"あなたは存在感があり、話題にすぐ入ってきて、自然に場をまとめます。人と一緒にいるのが好きな一方で、ちゃんと自分の意見も持っています。",flaw:"たった一つの提案を出したつもりなのに、いつの間にか全体の進行役になっている。",share:"私はコーギー型：小さくても、主役は自分。"},beagle:{name:"ビーグル",tags:["好奇心","探検","興味ナビ"],summary:"あなたは新しい手がかりに弱いです。面白い質問や、行ったことのないお店、通りすがりの音にもすぐ引きつけられます。自分で体験することを大切にするタイプです。",flaw:"「これだけ調べる」と言っておきながら、気づけばタブを18個開いている。",share:"私はビーグル型：人生は好奇心でナビゲート。"},"french-bulldog":{name:"フレンチブルドッグ",tags:["リラックス","ユーモア","陪伴感"],summary:"あなたは忙しさに執着せず、華やかな計画よりも心地良い・誠実・面白い人やことに関わりたいと思っています。場を和ませる天才です。",flaw:"複雑なことに気づくと、まず座って考えたいタイプ。",share:"私はフレンチブル型：リラックスは怠けじゃなく、暮らしの知恵。"}}},en:{meta:{title:"PawMatch — What dog breed are you?",description:"A lighthearted 10-question quiz to discover your dog personality."},language:{label:"Choose language",zh:"中文",ja:"日本語",en:"English"},home:{eyebrow:"PawMatch Personality Quiz",title:"If you were a dog, what breed would you be?",description:"\uD83D\uDC3E Discover your inner dog vibe \uD83D\uDC3E",start:"Start the quiz",meta:"10 questions \xb7 about 1 minute \xb7 just for fun"},quiz:{previous:"Previous",next:"Next",reveal:"Reveal my breed",progress:"{current} / {total}",home:"Back home"},result:{revealTitle:"Your dog personality is—",secondaryPrefix:"You also have a little {breed} in you",cuteFlawLabel:"Your adorably tiny flaw",saveImage:"Save image",share:"Share result",email:"Send by email",copy:"Copy result text",copied:"Copied",retry:"Take it again",loading:"Loading...",privacy:"Your PawMatch answers and result are processed entirely in your browser. This version requires no login and does not collect your name, email address, or complete answer set.",entertainment:"This quiz is for entertainment. Breed personalities are creative characterizations, not professional assessments of real breeds, individual dogs, or the user’s psychological traits."},notices:{entertainment:"This quiz is for entertainment. Breed personalities are creative characterizations, not professional assessments of real breeds, individual dogs, or the user’s psychological traits.",privacy:"Your PawMatch answers and result are processed entirely in your browser. This version requires no login and does not collect your name, email address, or complete answer set.",imageFallback:"We couldn’t create the image. Take a screenshot or copy the result text instead.",attachmentHint:"Image saved. Please attach it to your email manually."},questions:{q1:{text:"It’s finally the weekend — what do you want to do most?",options:{A:"Couch potato mode: movies and no one better call me",B:"Dinner and chat with familiar friends",C:"Walk, exercise, or hike in the park",D:"Head out on a spontaneous adventure to a new place"}},q2:{text:"You walk into a party full of strangers. What do you usually do?",options:{A:"After ten minutes, you’re already chatting with everyone",B:"Find one friendly-looking person and start talking",C:"Observe quietly and open up once you’re comfortable",D:"Stand beside a friend and quietly judge everyone"}},q3:{text:"When faced with a new task, what’s your first reaction?",options:{A:"Jump in and learn as you go",B:"Study it first, then make a plan",C:"Bring people along to build energy together",D:"See if I’m interested; if not, leave it for later"}},q4:{text:"A friend cancels a plan last minute. What do you do?",options:{A:"Immediately find another plan",B:"Feel a bit disappointed, then arrange your own fun",C:"Pretend you’re fine but quietly remember it",D:"Great, finally some alone time"}},q5:{text:"What word do your friends most often use to describe you?",options:{A:"Warm and energetic",B:"Reliable and gentle",C:"Smart and a bit serious",D:"Independent and distinctive"}},q6:{text:"When you get lost, how do you usually handle it?",options:{A:"Confidently keep going; the plot gets more interesting",B:"Open the map and fix the route quickly",C:"Ask someone for help and make a new friend",D:"I wasn’t lost; I just chose another path"}},q7:{text:"When a team suddenly falls into chaos, what are you like?",options:{A:"Lift the atmosphere and calm everyone down first",B:"Organize tasks and push things forward one step at a time",C:"Check who’s struggling and take care of them",D:"Point out the real problem even if people don’t love it"}},q8:{text:"If you could choose one superpower, what would you want?",options:{A:"Mind-reading: instantly know what everyone is thinking",B:"Clone power: complete everything at once",C:"Teleportation: go anywhere anytime",D:"Super senses: notice details others miss"}},q9:{text:"When faced with rules, which are you more like?",options:{A:"I follow them if they make sense, and discuss if not",B:"Rules make me feel safe, so I’ll follow them carefully",C:"First I’ll see if I can bend them a little",D:"I have my own rules, thank you"}},q10:{text:"How do you usually express affection?",options:{A:"Say it warmly and get closer",B:"Quietly remember and look after their needs",C:"Do fun things together and make memories",D:"I may not say it often, but I’ll always stay close"}}},breeds:{"golden-retriever":{name:"Golden Retriever",tags:["Warm","Friendly","Comfort"],summary:"You make it easy for people to relax. You listen well and naturally pull anyone who feels left out into the group. Your emotions are real, but you often lead with care for the atmosphere and others first.",flaw:"Sometimes you try so hard to keep everyone happy that you forget to rest yourself.",share:"I’m a Golden Retriever type: the comfort station in every friend group."},labrador:{name:"Labrador",tags:["Optimistic","Active","Team Spirit"],summary:"You tend to act first, then adjust as you go. When a new task appears, your energy often lifts everyone around you. You value teamwork and don’t mind doing a little extra when the moment matters.",flaw:"When you’re excited, you may agree to too much and only notice the overload later.",share:"I’m a Labrador type: optimistic, active, and ready to go."},poodle:{name:"Poodle",tags:["Smart","Sharp","Refined"],summary:"You notice fast, learn fast, and often catch details that others miss. You have your own standards for the environment, expression, and way things are done, and you dislike anything sloppy or half-done.",flaw:"When your standards are high, you can overthink one small detail for far longer than everyone else.",share:"I’m a Poodle type: clever, observant, and a bit particular."},"border-collie":{name:"Border Collie",tags:["Efficient","Focused","Strategist"],summary:"While others are still figuring out where to start, you’ve already quietly organized the steps. You enjoy understanding systems, finding patterns, and turning chaos into something doable.",flaw:"When you see inefficiency, it’s hard not to mentally rewrite everyone’s workflow.",share:"I’m a Border Collie type: I naturally turn chaos into a checklist."},"shiba-inu":{name:"Shiba Inu",tags:["Independent","Reserved","Principled"],summary:"You move at your own pace and keep your boundaries. Around strangers you may take time to warm up, but once you trust someone, your loyalty shows in stable, lasting actions rather than constant fuss.",flaw:"You may say “it’s fine” while already having one clearly correct answer in your head.",share:"I’m a Shiba Inu type: not overly eager, but once I’m in, I’m loyal for a long time."},husky:{name:"Husky",tags:["Free","Adventurous","Plot Twist"],summary:"Your world rarely feels boring because even a normal plan can turn into a whole new side quest in your hands. You’re curious, bold, and dislike being overly constrained by rules.",flaw:"Your speed occasionally outruns the plan, and only later do you notice the route is a little off.",share:"I’m a Husky type: free-spirited and self-made drama."},samoyed:{name:"Samoyed",tags:["Bright","Warm","Social Magnet"],summary:"You know how to bring ease and fun into a room, and you’re comfortable reaching out to others. You may look gentle, but you have clear preferences and you want your feelings and effort to be acknowledged.",flaw:"You look like you’re always smiling, but you may be quietly waiting for someone to say “you’re amazing today too.”",share:"I’m a Samoyed type: the one who gets everyone laughing again."},"german-shepherd":{name:"German Shepherd",tags:["Reliable","Protective","Strong Execution"],summary:"You take commitments seriously and instinctively step in when something needs handling. You may not be the loudest person in the room, but you are often the most reassuring one.",flaw:"Your sense of responsibility can make you carry tasks that aren’t actually yours.",share:"I’m a German Shepherd type: I don’t talk much, but I’ll catch the problem and hold it steady."},greyhound:{name:"Greyhound",tags:["Quiet","Sensitive","Relaxed"],summary:"You’re not short on energy, but you don’t want to waste it on pointless noise. You enjoy comfort, familiarity, and safe spaces, and you’re good at noticing subtle shifts in the atmosphere.",flaw:"If the sofa is comfortable enough, even the best plan can be postponed by five minutes — then another five.",share:"I’m a Greyhound type: I sprint when needed, and I lie down when it’s time to rest."},corgi:{name:"Corgi",tags:["Lively","Opinionated","Mini Captain"],summary:"You have strong presence and can quickly step into a conversation or naturally start organizing the situation. You like being with people, but that doesn’t mean you don’t have your own ideas — in fact, you often know what the group should do next.",flaw:"You meant to offer one suggestion, and somehow ended up acting as the whole event’s director.",share:"I’m a Corgi type: small in size, huge in hosting energy."},beagle:{name:"Beagle",tags:["Curious","Exploratory","Interest Navigator"],summary:"You have almost no defense against a fresh clue. A new question, a store you’ve never visited, or even a random sound on the street can send you off on a new direction. You like to experience things firsthand rather than just hear about them.",flaw:"You started with one question and somehow ended up with eighteen tabs open.",share:"I’m a Beagle type: my life runs on curiosity."},"french-bulldog":{name:"French Bulldog",tags:["Relaxed","Humorous","Companion"],summary:"You are not drawn to busyness or big plans to prove yourself. Comfortable, genuine, and interesting people and things are what deserve your time. You’re very good at defusing awkwardness with ease.",flaw:"You’re overly sensitive to trouble alarms and will want to sit down and think before anything gets complicated.",share:"I’m a French Bulldog type: relaxed is not the same as lazy — it’s life wisdom."}}}},n={zh:"中文",ja:"日本語",en:"English"},r="zh",s="pawmatch-locale"},4403:(e,a,t)=>{"use strict";t.r(a),t.d(a,{default:()=>r,metadata:()=>n});var o=t(2051);t(7272);let n={title:"PawMatch 趣味测试",description:"如果你是狗狗，你会是哪种犬种？"};function r({children:e}){return o.jsx("html",{lang:"zh-CN",children:o.jsx("body",{children:e})})}},7272:()=>{}};